#!/bin/sh
#
# The version this module reports has to be the version this repository is.
#
# src/ngx_http_tnt_version.h was generated by a Makefile that this
# repository does not have any more, so the value froze: it said v2.7.2
# while the module was 2.8.0, and ngx_http_tnt_module writes it to the
# error log at every configuration pass, which makes it the number anybody
# reading that log believes.  src/ngx_http_tnt_version.h.in, the template
# with @VERSION_STRING@ in it, was removed along with the generator.
#
#     ci/version.sh
#
# CHANGELOG.md is the source of truth, because that is the file a release
# cannot be made without touching.

set -eu

SRC=$(cd "$(dirname "$0")/.." && pwd)

want=$(sed -n 's/^## \([0-9][0-9.]*\)$/\1/p' "$SRC/CHANGELOG.md" | head -1)
[ -n "$want" ] || {
	echo "ci/version.sh: no version heading in CHANGELOG.md" >&2
	exit 1
}

hdr=$SRC/src/ngx_http_tnt_version.h

# The string carries a leading "v", the changelog heading does not.
got=$(sed -n 's/^#define NGX_HTTP_TNT_MODULE_VERSION_STRING  *"\(.*\)"/\1/p' "$hdr")
if [ "$got" != "v$want" ]; then
	echo "ci/version.sh: the version string is \"$got\", CHANGELOG.md says \"v$want\"" >&2
	exit 1
fi

if [ -e "$SRC/src/ngx_http_tnt_version.h.in" ]; then
	echo "ci/version.sh: src/ngx_http_tnt_version.h.in is back, and nothing substitutes it" >&2
	exit 1
fi

echo "ci/version.sh: v$want, and the header agrees"
